44	  });
45	
46	  const repo = values.repo ?? process.env.GITHUB_REPOSITORY ?? "";
47	  if (!values.type || !values.number || !values.dest || !repo) {
48	    console.error("usage: restore_workspace.ts --type issue|pr --number N --dest PATH [--repo owner/name]");
